+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private final MessageService messageService;
+
+    private final TextField nameField = new TextField("Name");
+    private final EmailField emailField = new EmailField("Email");
+    private final TextField phoneField = new TextField("Phone");
+    private final TextArea messageField = new TextArea("Message");
+    private final Button sendButton = new Button("Send");
+    private final Grid<ContactMessage> grid = new Grid<>(ContactMessage.class, false);
+
+    public ContactView(MessageService messageService) {
+        this.messageService = messageService;
+
+        add(new H1("Contact"));
+        add(new RouterLink("About", AboutView.class));
+
+        sendButton.addClickListener(event -> send());
+        sendButton.addClickShortcut(Key.ENTER);
+
+        nameField.addValueChangeListener(event -> sendButton.setEnabled(true));
+        emailField.addValueChangeListener(event -> sendButton.setEnabled(true));
+        phoneField.addValueChangeListener(event -> sendButton.setEnabled(true));
+        messageField.addValueChangeListener(event -> sendButton.setEnabled(true));
+
+        add(new VerticalLayout(nameField, emailField, phoneField, messageField, sendButton));
+
+        grid.addColumn(ContactMessage::name).setHeader("Name");
+        grid.addColumn(ContactMessage::email).setHeader("Email");
+        grid.addColumn(ContactMessage::phone).setHeader("Phone");
+        grid.addColumn(ContactMessage::message).setHeader("Message");
+        add(grid);
+
+        refreshGrid();
+    }
+
+    private void refreshGrid() {
+        grid.setItems(messageService.findAll());
+    }
+
+    private void send() {
+        clearErrors();
+
+        String name = nameField.getValue();
+        String email = emailField.getValue();
+        String phone = phoneField.getValue();
+        String message = messageField.getValue();
+
+        boolean valid = true;
+
+        if (isBlank(name)) {
+            nameField.setInvalid(true);
+            nameField.setErrorMessage("Name is required");
+            valid = false;
+        }
+
+        if (!isBlank(email)) {
+            if (!isValidEmail(email)) {
+                emailField.setInvalid(true);
+                emailField.setErrorMessage("Enter a valid e-mail address");
+                valid = false;
+            }
+        } else if (isBlank(phone)) {
+            emailField.setInvalid(true);
+            emailField.setErrorMessage("Give an e-mail address or a phone number");
+            valid = false;
+        }
+
+        if (isBlank(message)) {
+            messageField.setInvalid(true);
+            messageField.setErrorMessage("Message is required");
+            valid = false;
+        } else if (message.length() > 500) {
+            messageField.setInvalid(true);
+            messageField.setErrorMessage("Message must be at most 500 characters");
+            valid = false;
+        }
+
+        if (!valid) {
+            return;
+        }
+
+        messageService.add(new ContactMessage(name, email, phone, message, LocalDateTime.now()));
+        refreshGrid();
+
+        nameField.clear();
+        emailField.clear();
+        phoneField.clear();
+        messageField.clear();
+
+        Notification.show("Message sent");
+        sendButton.setEnabled(false);
+    }
+
+    private void clearErrors() {
+        nameField.setInvalid(false);
+        emailField.setInvalid(false);
+        messageField.setInvalid(false);
+    }
+
+    private boolean isValidEmail(String email) {
+        return !new EmailValidator("invalid").apply(email, new ValueContext()).isError();
+    }
+
+    private static boolean isBlank(String value) {
+        return value == null || value.isBlank();
+    }
+
+    private boolean hasUnsavedData() {
+        return !isBlank(nameField.getValue()) || !isBlank(emailField.getValue())
+                || !isBlank(phoneField.getValue()) || !isBlank(messageField.getValue());
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (hasUnsavedData()) {
+            confirmNavigation(event.postpone());
+        }
+    }
+
+    private void confirmNavigation(BeforeLeaveEvent.ContinueNavigationAction action) {
+        Dialog dialog = new Dialog();
+        dialog.setCloseOnEsc(false);
+        dialog.setCloseOnOutsideClick(false);
+        dialog.add(new Span("You have unsent changes. Do you want to discard them?"));
+
+        Button keepEditing = new Button("Keep editing", event -> dialog.close());
+        Button discard = new Button("Discard", event -> {
+            dialog.close();
+            action.proceed();
+        });
+
+        dialog.getFooter().add(keepEditing, discard);
+        dialog.open();
+    }
+}
