+package com.example.contact;
+
+import java.util.Collections;
+import java.util.LinkedList;
+import java.util.List;
+import org.springframework.stereotype.Service;
+
+@Service
+public class MessageService {
+
+    private final LinkedList<ContactMessage> messages = new LinkedList<>();
+
+    public synchronized void add(ContactMessage message) {
+        messages.addFirst(message);
+    }
+
+    public synchronized List<ContactMessage> findAll() {
+        return Collections.unmodifiableList(new LinkedList<>(messages));
+    }
+}
